import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-card-2-label';

  const pos = config.scenePosition?.position ?? [3.2, 1, 0.06];
  const rot = config.scenePosition?.rotation ?? [0, 0, 0];
  const scl = config.scenePosition?.scale ?? [1, 1, 1];
  group.position.set(...pos);
  group.rotation.set(...rot);
  group.scale.set(...scl);

  const width = 1.6;
  const height = width * (320 / 512);

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const imgTex = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  imgTex.colorSpace = THREE.SRGBColorSpace;

  const uvNode = uv();
  const texNode = texture(imgTex, uvNode);

  const inkColor = vec4(0.086, 0.086, 0.114, 1.0);
  const gradFactor = uvNode.y;
  const gradTint = mix(inkColor, vec4(1, 1, 1, 1), gradFactor.mul(0.15).add(0.85));

  material.colorNode = texNode.mul(gradTint);

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'collection-card-2-image';
  group.add(plane);

  let textMesh = null;
  try {
    textMesh = createTextMesh({
      text: 'Collection 3',
      font: 'Lora',
      weight: 400,
      size: 0.34,
      color: '#e8ecf2',
      atlas: ctx.fontAtlas,
      align: 'center',
    });
    textMesh.name = 'collection-card-2-label-text';
    textMesh.position.set(0, -height / 2 + 0.18, 0.01);
    group.add(textMesh);
  } catch (e) {
    // font atlas unavailable — skip text rendering gracefully
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (imgTex) imgTex.dispose();
    if (textMesh) {
      textMesh.geometry?.dispose?.();
      if (Array.isArray(textMesh.material)) {
        textMesh.material.forEach((m) => m.dispose());
      } else {
        textMesh.material?.dispose?.();
      }
    }
  };

  return group;
}
